rg=crypto_gen('Random',[1320,140],'rnd',16);dv=code('Derive OTP',[1540,140],CODE['otp_derive']);ho=crypto_hmac('Hash OTP',[1760,140],"={{ $json.hmac_value }}","={{ $('Config').first().json.api_key }}");br=code('Build OTP row',[1980,140],CODE['otp_row'])
so=sheet('Save OTP',[2200,140],'OTP','append',(OTP_COLS,'$json.row'));rk=respond('Respond OTP Sent',[2420,60],"={{ JSON.stringify($('Build OTP row').first().json.response) }}")
wc=wa_cfg([2420,240]);ws=wa_http('WhatsApp: login code',[2640,240],'',"{messaging_product:'whatsapp',to:'91'+$('Build OTP row').first().json.phone,type:'template',template:{name:'login_otp',language:{code:'en'},components:[{type:'body',parameters:[{type:'text',text:$('Build OTP row').first().json.otp}]},{type:'button',sub_type:'url',index:'0',parameters:[{type:'text',text:$('Build OTP row').first().json.otp}]}]}}")
CFGN='Config (verify)'
