hs=crypto_hmac('Hash submitted OTP',[660,700],"={{ $json.body.otp + '|' + String($json.body.phone).replace(/\\D/g,'').slice(-10) }}","={{ $('Config (verify)').first().json.api_key }}");rv=sheet('Read OTP (verify)',[880,700],'OTP','read');vo=code('Verify OTP',[1100,700],CODE['otp_verify']);cc=ifnode('Code correct?',[1320,700],'={{ $json.ok }}','boolean','true')
tk=crypto_gen('Session token',[1540,620],'token',24);sr=code('Build session row',[1760,620],CODE['session_row']);ss=sheet('Save session',[1980,620],'Sessions','append',(SESS_COLS,'$json.row'));mu=sheet_update('Mark OTP used',[2200,620],'OTP',['otp_id','attempts','used'],'otp_id',"$('Verify OTP').first().json.upd");rs=respond('Respond Logged In',[2420,620],"={{ JSON.stringify($('Build session row').first().json.response) }}")
ha=ifnode('Wrong code?',[1540,800],'={{ $json.upd ? true : false }}','boolean','true');wa=sheet_update('Count wrong attempt',[1760,760],'OTP',['otp_id','attempts','used'],'otp_id',"$('Verify OTP').first().json.upd");rb=respond('Respond Code Error',[1980,800],"={{ JSON.stringify($('Verify OTP').first().json.response) }}",400)
CFGN='Config (account)'
w3=webhook('Account Webhook',[0,1200],'vaigai-account','GET');c3=config([220,1200],'Config (account)');r3=sheet('Read Sessions',[440,1200],'Sessions','read');cs=code('Check session (account)',[660,1200],CODE['check_session_account']);sv=ifnode('Session valid?',[880,1200],'={{ $json.ok }}','boolean','true');ru=respond('Respond Session Expired',[1100,1380],"={{ JSON.stringify($json.response) }}",401)
ro2=sheet('Read Orders (account)',[1100,1140],'Orders','read');rs2=sheet('Read Subscriptions (account)',[1320,1140],'Subscriptions','read');ba=code('Build account',[1540,1140],CODE['build_account']);ra=respond('Respond Account',[1760,1140],"={{ JSON.stringify($json.response) }}")
CFGN='Config (sub)'
w4=webhook('Sub Update Webhook',[0,1700],'vaigai-sub-update');c4=config([220,1700],'Config (sub)');r4=sheet('Read Sessions (sub)',[440,1700],'Sessions','read');cs2=code('Check session (sub)',[660,1700],CODE['check_session_sub']);sv2=ifnode('Session valid? (sub)',[880,1700],'={{ $json.ok }}','boolean','true');ru2=respond('Respond Session Expired (sub)',[1100,1880],"={{ JSON.stringify($json.response) }}",401)
rs3=sheet('Read Subscriptions (sub)',[1100,1640],'Subscriptions','read');ap=code('Apply change',[1320,1640],CODE['apply_sub_change']);cv=ifnode('Change valid?',[1540,1640],'={{ $json.ok }}','boolean','true');us=sheet_update('Update Subscriptions',[1760,1580],'Subscriptions',['sub_id','status','skip_dates'],'sub_id',"$('Apply change').first().json.upd");ro3=respond('Respond Updated',[1980,1580],"={{ JSON.stringify($('Apply change').first().json.response) }}");rbad=respond('Respond Change Error',[1760,1780],"={{ JSON.stringify($json.response) }}",400)
n7=note("CUSTOMER ACCOUNT\nPasswordless login: customer enters mobile, gets a 6 digit code on WhatsApp (template login_otp), codes are stored hashed, expire in 5 minutes, max 3 requests per 10 minutes and 5 wrong tries. Session token lasts 30 days. Create tabs OTP and Sessions (see sheets/). Customers can see their last 15 orders, repeat an order, pause, resume, cancel or skip a delivery (cut-off 9 PM the day before). Subscriptions tab needs a phone column that matches the customer's mobile.\n"+STICKY_KEY,[0,-120],760,300)
